import{_ as t,o,c as l,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Developer Monthly 2022-06-01","description":"","frontmatter":{"title":"Ceph Developer Monthly 2022-06-01","date":"2022-06-01T00:00:00.000Z","updated":"2022-06-03T00:00:00.000Z","tags":["Ceph","BlueStore","Zero Block Detection","Storage Optimization","Performance Counters"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Developer_Monthly_2022-06-01.md","filePath":"posts/2022/Ceph_Developer_Monthly_2022-06-01.md","lastUpdated":1780460162000}'),r={name:"posts/2022/Ceph_Developer_Monthly_2022-06-01.md"};function s(n,e,a,i,_,c){return o(),l("div",null,[...e[0]||(e[0]=[p("<p>本次Ceph开发者月度会议主要讨论了以下几个关键议题：</p><ol><li><p><strong>对象存储中的“洞”问题</strong>：会议中解释了对象内部有洞和对象内部有洞但被分配之间的区别，这主要涉及到加密用例。如果一个区域被分配但没有数据（即有洞），在读取时不需要解密，直接返回零；但如果这个区域实际包含了加密后的数据，即使这些数据是全零，也需要先解密再返回给用户。</p></li><li><p><strong>BlueStore的零块检测功能</strong>：讨论了BlueStore中零块检测功能的实现及其对存储效率的影响。特别是，该功能在处理厚置备RBD镜像时可能会导致性能问题，因为它会将零块写入磁盘。</p></li><li><p><strong>改进数据布局和语义</strong>：为了解决零块检测问题，会议提出了在对象存储层引入逻辑范围和物理范围的区别，并仅对物理范围进行转换。此外，还讨论了引入新的逻辑范围类型，以更好地支持加密用例。</p></li><li><p><strong>性能计数器统计收集</strong>：讨论了使用Boost Accumulators库来改进Ceph的性能计数器统计收集。Boost Accumulators提供了多种统计方法，可以在收集多个统计量时提高效率。</p></li><li><p><strong>大规模测试</strong>：讨论了利用BlueStore的零块检测功能进行大规模测试的计划，以模拟大型集群的行为，而无需使用大量物理硬件。</p></li></ol><p>会议决定采取以下行动：</p><ul><li>文档化和澄清OSD操作的语义，特别是在处理数据布局和转换方面。</li><li>测试Boost Accumulators库在Ceph性能计数器中的应用，以评估其效率。</li><li>开发和实施大规模测试，以验证Ceph在高负载情况下的性能和稳定性。</li></ul>",4)])])}const d=t(r,[["render",s]]);export{h as __pageData,d as default};
